                <View style={styles.tabToggleRowBarContainer}>
                  <TouchableOpacity 
                    style={[styles.segmentTabButton, activeTab === 'CONSULTATIONS' && styles.activeSegmentTabButton]}
                    onPress={() => setActiveTab('CONSULTATIONS')}
